<script>
  // Simple stepper logic
  document.querySelectorAll('.stepper').forEach(stepper => {
    const decBtn = stepper.querySelector('.dec');
    const incBtn = stepper.querySelector('.inc');
    const qtySpan = stepper.querySelector('.qty');
    const item = stepper.closest('.item');
    const price = parseFloat(item.dataset.price);
    const totalSpan = item.querySelector('.item-total');

    function update() {
      let qty = parseInt(qtySpan.textContent);
      if (qty < 1) qty = 1;
      qtySpan.textContent = qty;
      totalSpan.textContent = (price * qty).toFixed(2);
      updateSummary();
    }

    decBtn.addEventListener('click', () => {
      let qty = parseInt(qtySpan.textContent);
      if (qty > 1) {
        qtySpan.textContent = qty - 1;
        update();
      }
    });

    incBtn.addEventListener('click', () => {
      let qty = parseInt(qtySpan.textContent);
      qtySpan.textContent = qty + 1;
      update();
    });
  });

  function updateSummary() {
    let subtotal = 0;
    document.querySelectorAll('.item').forEach(item => {
      subtotal += parseFloat(item.querySelector('.item-total').textContent);
    });
    const delivery = 5;
    const vat = subtotal * 0.05;
    const total = subtotal + delivery + vat;
    document.getElementById('subtotal').textContent = subtotal.toFixed(2) + ' AED';
    document.getElementById('vat').textContent = vat.toFixed(2) + ' AED';
    document.getElementById('total').textContent = total.toFixed(2) + ' AED';
  }

  // back button
  document.getElementById('back').addEventListener('click', () => {
    history.back();
  });
</script>
